import { walletReceiptLog } from './wallet-receipt.js';
import { walletAbi } from './wallet-abi.js';
import { abi as run66GAME } from '../chain/generated/game.js';
import { accountArg } from './wallet-id.js';
// /app/app/foil-claim.js — foil match claim write path.
//
// claimFoilMatch(address player, uint256 day, uint256 ticketIndex) on GAME
// (delegatecalled into DegenerusGameFoilPackModule, audit 9ee8986d
// FoilPackModule.sol:506). Run 56 (audit 224de529) also takes a trailing
// `uint8 drawKind` (0 = main set, 1 = bonus set); from run 57 a day draws one
// board, so the claim and its FoilMatchClaimed event drop it. The calldata
// follows the active read schema (chain/schema.js). Permissionless: the win
// credits `player`, never the caller; a tuple pays at most once.
//
// The payout is an isolated Degenerette box-spin staking the tier's faces
// (see FOIL_TIER_FACES_* below — one face = one ticket of value, 40/40/20
// ETH/FLIP/WWXRP lanes; T8 also grants a half whale pass). The claim
// receipt therefore carries a BoxSpin event that lootbox-legs.js decodes into
// reveal-overlay reels.
//
// Mirrors lootbox.js structure: closure-form sendTx (Phase 58), static-call
// pre-flight (Phase 56 CF-03), structured revert decode (CF-02), contract
// factory test seam.

import { sendTx, getProvider, ethers } from './contracts.js';
import { requireStaticCall } from './static-call.js';
import { decodeRevertReason, register } from './reason-map.js';
import { CONTRACTS } from './chain-config.js';
import { isRun56Schema } from '../chain/schema.js';

const FOIL_CLAIM_ERRORS = ['error NoClaimableMatch()', 'error GameOver()'];
/** Run 56 (audit 224de529): a claim names the draw it matched (0 = main, 1 = bonus). */
export const FOIL_CLAIM_ABI_RUN56 = Object.freeze([
  'function claimFoilMatch(address player, uint256 day, uint256 ticketIndex, uint8 drawKind)',
  ...FOIL_CLAIM_ERRORS,
  'event FoilMatchClaimed(address indexed player, uint24 indexed day, uint256 ticketIndex, uint8 drawKind, uint8 tier, uint256 faces)',
]);
/** Run 57+ (audit 9ee8986d): one board a day, so no drawKind anywhere. */
export const FOIL_CLAIM_ABI_CURRENT = Object.freeze([
  'function claimFoilMatch(address player, uint256 day, uint256 ticketIndex)',
  ...FOIL_CLAIM_ERRORS,
  'event FoilMatchClaimed(address indexed player, uint24 indexed day, uint256 ticketIndex, uint8 tier, uint256 faces)',
]);
/** The claim ABI of the deployment the site reads. */
export function foilClaimAbi() { return isRun56Schema() ? FOIL_CLAIM_ABI_RUN56 : FOIL_CLAIM_ABI_CURRENT; }

// These errors are reachable before the payout spin. In particular,
// NoClaimableMatch is the normal permissionless race: another caller already
// settled the immutable (player, day, ticket, draw) tuple between our indexed
// read and static call.
register('NoClaimableMatch', {
  code: 'NoClaimableMatch',
  userMessage: 'This foil match is already settled.',
  recoveryAction: 'Refresh foil results.',
});

/** Tier → faces staked into the payout spin (FoilPackModule FOIL_FACES_T4..T8). */
// Run 56 (audit 224de529, FoilPackModule.sol:168-172): scaled x4 in audit 2c2e2d95.
export const FOIL_TIER_FACES_RUN56 = Object.freeze({ 4: 8, 5: 24, 6: 140, 7: 1_600, 8: 40_000 });
// Run 57+ (audit 9ee8986d, FoilPackModule.sol:168-172): doubled, with one board a day to match.
export const FOIL_TIER_FACES = Object.freeze({ 4: 16, 5: 48, 6: 280, 7: 3_200, 8: 80_000 });
/** The face table of the deployment the site reads. */
export function foilTierFaces() { return isRun56Schema() ? FOIL_TIER_FACES_RUN56 : FOIL_TIER_FACES; }

let _contractFactory = null;

/** Test-only: replace the `new Contract(...)` construction with a fake. */
export function __setContractFactoryForTest(fn) { _contractFactory = fn; }
export function __resetContractFactoryForTest() { _contractFactory = null; }

function _buildContract(signerOrProvider) {
  if (_contractFactory) return _contractFactory(signerOrProvider);
  return new ethers.Contract(CONTRACTS.GAME, walletAbi(foilClaimAbi(), run66GAME), signerOrProvider);
}

function _structuredRevertError(error, context) {
  const decoded = decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || `Failed: ${context}`);
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

/**
 * @param {{player: string, day: number|bigint, ticketIndex: number, drawKind?: number}} args
 *   drawKind is sent only to a run-56 deployment.
 * @returns {Promise<{receipt, contract}>}
 */
export async function claimFoilMatch(args) {
  const player = String(args.player || '');
  if (!player) throw new Error('No player to claim for.');
  const day = BigInt(args.day);
  const ticketIndex = BigInt(args.ticketIndex);
  const id = await accountArg(player);
  const callArgs = isRun56Schema()
    ? [player, day, ticketIndex, Number(args.drawKind) & 1]
    : [id, day, ticketIndex];

  const provider = getProvider();
  const signer = provider ? await provider.getSigner() : null;

  if (signer) {
    const contract = _buildContract(signer);
    const sim = await requireStaticCall(
      contract,
      'claimFoilMatch',
      callArgs,
      signer
    );
    if (!sim.ok) throw _structuredRevertError(sim.error, 'static-call claimFoilMatch');
  }

  const receipt = await sendTx(
    (s) => {
      const c = _buildContract(s);
      return c.claimFoilMatch(...callArgs);
    },
    'Claim foil match'
  );

  const contract = _buildContract(provider);
  return { receipt, contract };
}

/**
 * Parse FoilMatchClaimed entries from a claim receipt. A run-57+ claim always
 * matched the day's one board, which the site files as drawKind 0 (main).
 * @returns {Array<{player: string, day: number, ticketIndex: number, drawKind: number, tier: number, faces: number}>}
 */
export function parseFoilMatchClaimedFromReceipt(receipt, contract) {
  const out = [];
  if (!receipt || !Array.isArray(receipt.logs)) return out;
  // Positional fallbacks follow the active event shape: run 56 carries drawKind at [3].
  const shift = isRun56Schema() ? 1 : 0;
  for (const log of receipt.logs) {
    try {
      const parsed = walletReceiptLog(log, contract.interface);
      if (parsed && parsed.name === 'FoilMatchClaimed') {
        out.push({
          player: String(parsed.args.player ?? parsed.args[0]),
          day: Number(parsed.args.day ?? parsed.args[1]),
          ticketIndex: Number(parsed.args.ticketIndex ?? parsed.args[2]),
          drawKind: shift ? Number(parsed.args.drawKind ?? parsed.args[3]) : 0,
          tier: Number(parsed.args.tier ?? parsed.args[3 + shift]),
          faces: Number(parsed.args.faces ?? parsed.args[4 + shift]),
        });
      }
    } catch (_e) { /* foreign log — skip */ }
  }
  return out;
}
